  function eventPreview(event){const candidate=event.publicUrl||`${httpsRoot}bamedicale.com/events/${encodeURIComponent(event.id)}.html`;return`<h2>Seminar preview</h2><p class="status-note">This preview is private and does not publish the event.</p><div class="preview-grid"><div><span>Title</span><strong>${esc(event.title)}</strong></div><div><span>State</span>${status(scopeApi.classifyEvent(event,Date.now())==="excluded"?"Draft":scopeApi.classifyEvent(event,Date.now()))}</div><div><span>Schedule</span><strong>${esc(dateTimeText(event.startAt))} – ${esc(dateTimeText(event.endAt))}</strong></div><div><span>Format</span><strong>${esc(event.format||"Not available")}</strong></div><div><span>Event URL</span><code>${esc(candidate)}</code></div><div><span>Registration URL / QR</span><strong>${esc(event.publication?.typeData?.publication?.registration||"Pending generation")}</strong></div><div><span>Commercial</span><strong>${esc(event.commercial||"Pending")}${event.commercial==="Paid"?` · ${esc(event.currency)} ${fmt(event.price)}`:""}</strong></div><div><span>Location</span><strong>${esc(event.format==="Online"?event.platform:[event.venue,event.address].filter(Boolean).join(", "))}</strong></div><div><span>Calendar</span><strong>${event.startAt?"Google Calendar and .ics ready":"Not available"}</strong></div><div><span>Event Tools</span><strong>Admin workspace ready</strong></div></div><div class="dialog-actions"><button class="button" value="cancel">Close</button><button class="button" disabled>Publish — Not Connected</button></div>`;}
