  function videoEvidence(title){const text=String(title||""),tags=["BA Medicale Originals"];if(/\b(thyroid|ti-?rads)\b/i.test(text))tags.push("Thyroid");if(/\b(cancer|tumou?r|neoplas)/i.test(text))tags.push("Cancer");if(/\b(diagnos|imaging|ultrasound|patholog|cytolog)/i.test(text))tags.push("Diagnostics");const primaryAudience=/\b(clinical|diagnos|therapy|management|imaging|ultrasound|patholog|cytolog|ti-?rads)\b/i.test(text)?"Healthcare Professionals":/\b(definition|early detection|awareness|public)\b/i.test(text)?"Public":"Needs Review";return{primaryAudience,tags:[...new Set(tags)],primaryTopic:tags.includes("Diagnostics")?"Diagnostics":"Medical Education"};}
  function videoPosterFile(file,fraction,title){return new Promise((resolve,reject)=>{const video=document.createElement("video"),url=URL.createObjectURL(file),cleanup=()=>{URL.revokeObjectURL(url);video.removeAttribute("src");};video.preload="metadata";video.muted=true;video.playsInline=true;video.onerror=()=>{cleanup();reject(new Error("The MP4 could not be decoded for poster generation."));};video.onloadedmetadata=()=>{if(!Number.isFinite(video.duration)||video.duration<=0){cleanup();reject(new Error("The MP4 duration could not be read."));return;}video.currentTime=Math.min(Math.max(video.duration*Number(fraction||.12),0),Math.max(video.duration-.05,0));};video.onseeked=()=>{try{const canvas=document.createElement("canvas"),width=1080,height=1920,ctx=canvas.getContext("2d");canvas.width=width;canvas.height=height;ctx.fillStyle="#f7f1e7";ctx.fillRect(0,0,width,height);ctx.fillStyle="#a6192e";ctx.fillRect(0,0,width,190);ctx.fillRect(0,height-180,width,180);const frameTop=190,frameHeight=height-370,scale=Math.min(width/video.videoWidth,frameHeight/video.videoHeight),drawWidth=video.videoWidth*scale,drawHeight=video.videoHeight*scale,x=(width-drawWidth)/2,y=frameTop+(frameHeight-drawHeight)/2;ctx.drawImage(video,x,y,drawWidth,drawHeight);ctx.fillStyle="#fff";ctx.font="600 34px 'IBM Plex Sans', sans-serif";ctx.fillText("BA MEDICALE ORIGINALS",64,105);ctx.font="600 38px 'IBM Plex Sans', sans-serif";const words=String(title||"BA Medicale Original").split(/\s+/),lines=[];let line="";words.forEach(word=>{const next=(line+" "+word).trim();if(ctx.measureText(next).width>width-128&&line){lines.push(line);line=word;}else line=next;});if(line)lines.push(line);lines.slice(0,2).forEach((value,index)=>ctx.fillText(value,64,height-105+index*44));canvas.toBlob(blob=>{cleanup();if(!blob){reject(new Error("The generated poster could not be encoded."));return;}resolve(new File([blob],"generated-originals-poster.jpg",{type:"image/jpeg",lastModified:Date.now()}));},"image/jpeg",.92);}catch(error){cleanup();reject(error);}};video.src=url;});}
